import re

def tokenize_hbs(s):
    # Tokenize handlebars expression string
    tokens = []
    i = 0
    while i < len(s):
        if s[i].isspace():
            i += 1
            continue
        if s[i] in "()":
            tokens.append(s[i])
            i += 1
            continue
        if s[i] in "\"'":
            quote = s[i]
            i += 1
            start = i
            while i < len(s) and s[i] != quote:
                if s[i] == "\\" and i + 1 < len(s):
                    i += 2
                else:
                    i += 1
            tokens.append(("STRING", s[start:i]))
            if i < len(s): i += 1
            continue
        if s[i] == "[":
            start = i + 1
            while i < len(s) and s[i] != "]":
                i += 1
            tokens.append(("ID", s[start:i]))
            if i < len(s): i += 1
            continue
        start = i
        while i < len(s) and not s[i].isspace() and s[i] not in "()\"'[]":
            i += 1
        tok = s[start:i]
        if tok.isdigit() or (tok.startswith("-") and tok[1:].isdigit()):
            tokens.append(("INT", int(tok)))
        elif tok == "true":
            tokens.append(("BOOL", True))
        elif tok == "false":
            tokens.append(("BOOL", False))
        else:
            tokens.append(("ID", tok))
    return tokens

print(tokenize_hbs("bold(fixed_size 19 fblog_timestamp)"))
