            while i < len(s) and s[i] != "]":
                i += 1
            tokens.append(("ID", s[start:i]))
            if i < len(s): i += 1
            continue
        start = i
        while i < len(s) and not s[i].isspace() and s[i] not in "()\"'[]":
            i += 1
        tok = s[start:i]
        if tok.isdigit() or (tok.startswith("-") and tok[1:].isdigit()):
            tokens.append(("INT", int(tok)))
        elif tok == "true":
            tokens.append(("BOOL", True))
        elif tok == "false":
            tokens.append(("BOOL", False))
        else:
            tokens.append(("ID", tok))
    return tokens

def parse_expr_tokens(tokens, ctx):
    idx = 0
    def eval_next():
        nonlocal idx
        if idx >= len(tokens):
            return ""
        tok = tokens[idx]
        if tok == "(":
            idx += 1
            res = eval_next()
            if idx < len(tokens) and tokens[idx] == ")":
                idx += 1
            return res
        idx += 1
        if isinstance(tok, tuple):
            ttype, val = tok
            if ttype == "STRING":
                return val
            elif ttype in ("INT", "BOOL"):
                return val
            elif ttype == "ID":
                if val in HELPERS:
                    func = HELPERS[val]
                    args = []
                    while idx < len(tokens) and tokens[idx] != ")":
                        args.append(eval_next())
                    return func(*args)
                else:
                    return ctx.get(val, "")
        return ""

    return eval_next()

def render_hbs(tmpl, ctx):
    # Process {{#if cond}} ... {{else}} ... {{/if}}
    def render_block(m):
        cond_str = m.group(1).strip()
        body = m.group(2)
        true_body = body
        false_body = ""
        if "{{else}}" in body:
            parts = body.split("{{else}}", 1)
            true_body, false_body = parts[0], parts[1]

        cond_val = parse_expr_tokens(tokenize_hbs(cond_str), ctx)
        if cond_val and cond_val != "0" and cond_val != "false":
            return render_hbs(true_body, ctx)
        else:
            return render_hbs(false_body, ctx)

    s = re.sub(r'\{\{#if\s+(.*?)\}\}(.*?)\{\{/if\}\}', render_block, tmpl, flags=re.DOTALL)

    # Process {{ expr }}
    def render_tag(m):
        expr_str = m.group(1).strip()
        val = parse_expr_tokens(tokenize_hbs(expr_str), ctx)
        return str(val)

    s = re.sub(r'\{\{(.*?)\}\}', render_tag, s)
    return s

# --- Lua Initialization & Filter ---
def sanitize_key(k):
    return re.sub(r'[^a-zA-Z]', '_', str(k))

def to_lua_val(v, inside_array=False):
    if inside_array and isinstance(v, (list, dict)):
        return '"unsupported"'
    if v is None:
        return "nil"
    elif isinstance(v, bool):
        return "true" if v else "false"
    elif isinstance(v, (int, float)):
        return str(v)
    elif isinstance(v, str):
        escaped = v.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t")
        return f'"{escaped}"'
    elif isinstance(v, list):
        elems = [to_lua_val(x, inside_array=True) for x in v]
        return "{" + ",".join(elems) + "}"
    elif isinstance(v, dict):
        items = []
        for k, sub_v in sorted(v.items(), key=lambda x: str(x[0])):
            items.append(f"{sanitize_key(k)} = {to_lua_val(sub_v, inside_array=False)}")
        return "{" + ",".join(items) + "}"
    return "nil"

def generate_lua_init(json_obj):
    lines = []
    for k, v in sorted(json_obj.items(), key=lambda x: sanitize_key(x[0])):
        san_k = sanitize_key(k)
        lines.append(f"{san_k} = {to_lua_val(v)}")
    return "\n".join(lines)

class LuaEnv(dict):
    def __getitem__(self, item):
        return self.get(item, None)

def lua_to_python_expr(expr):
    strings = []
    def save_str(m):
        strings.append(m.group(0))
        return f"__STR_{len(strings)-1}__"

    s = re.sub(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'', save_str, expr)
    s = re.sub(r'\b~=\b|~=', '!=', s)
    s = re.sub(r'\band\b', ' and ', s)
    s = re.sub(r'\bor\b', ' or ', s)
    s = re.sub(r'\bnot\b', ' not ', s)
    s = re.sub(r'\bnil\b', ' None ', s)
    s = re.sub(r'\btrue\b', ' True ', s)
    s = re.sub(r'\bfalse\b', ' False ', s)
    s = re.sub(r'\.\.', '+', s)

    s = re.sub(r'\bstring\.find\b', 'lua_string_find', s)
    s = re.sub(r'\bstring\.match\b', 'lua_string_match', s)
    s = re.sub(r'\bstring\.lower\b', 'lua_string_lower', s)
    s = re.sub(r'\bstring\.upper\b', 'lua_string_upper', s)

    for i, st in enumerate(strings):
        s = s.replace(f"__STR_{i}__", st)
    return s

def lua_string_find(s, pattern):
    if s is None or pattern is None:
        return None
    py_pat = pattern.replace('%d', r'\d').replace('%a', r'[a-zA-Z]').replace('%w', r'\w').replace('%s', r'\s')
    m = re.search(py_pat, str(s))
    if m:
        return (m.start() + 1, m.end())
    return None

def lua_string_match(s, pattern):
    if s is None or pattern is None:
        return None
    py_pat = pattern.replace('%d', r'\d').replace('%a', r'[a-zA-Z]').replace('%w', r'\w').replace('%s', r'\s')
    m = re.search(py_pat, str(s))
    if m:
        return m.group(1) if m.groups() else m.group(0)
    return None

def eval_lua_filter(expr, env, no_implicit_return=False):
    py_expr = lua_to_python_expr(expr)
    if "return " in py_expr:
        py_expr = py_expr.split("return ", 1)[1]
    try:
        res = eval(py_expr, {"__builtins__": None, "lua_string_find": lua_string_find, "lua_string_match": lua_string_match, "True": True, "False": False, "None": None}, env)
        return bool(res)
    except Exception as e:
        raise RuntimeError(str(e))

# --- Context Value Substitution (-s) ---
def format_ctx_val(v):
    if v is None:
        return "\x1b[1mnull\x1b[0m"
    elif isinstance(v, bool):
        return "\x1b[1;32mtrue\x1b[0m" if v else "\x1b[1;31mfalse\x1b[0m"
    elif isinstance(v, (int, float)):
        return f"\x1b[1;36m{v}\x1b[0m"
    elif isinstance(v, str):
        return f"\x1b[1;33m{v}\x1b[0m"
    elif isinstance(v, list):
        elems = "\x1b[2m, \x1b[0m".join(format_ctx_val(x) for x in v)
        return f"\x1b[2m[\x1b[0m{elems}\x1b[2m]\x1b[0m"
    elif isinstance(v, dict):
        items = []
        for k in sorted(v.keys()):
            val_str = format_ctx_val(v[k])
            items.append(f"\x1b[35m{k}\x1b[0m\x1b[2m: \x1b[0m{val_str}")
        kv_pairs = "\x1b[2m, \x1b[0m".join(items)
        return f"\x1b[2m{{\x1b[0m{kv_pairs}\x1b[2m}}\x1b[0m"
    return str(v)

def substitute_placeholders(msg, ctx_data, pf="{key}"):
    prefix = pf.split("key")[0]
    suffix = pf.split("key")[1]
    pattern = re.escape(prefix) + r'([a-zA-Z0-9_-]+)' + re.escape(suffix)

    def repl(m):
        key = m.group(1)
        val = None
        found = False
        if isinstance(ctx_data, dict):
            if key in ctx_data:
                val = ctx_data[key]
                found = True
        elif isinstance(ctx_data, list):
            if key.isdigit():
                idx = int(key)
                if 0 <= idx < len(ctx_data):
                    val = ctx_data[idx]
                    found = True
        if found:
            return format_ctx_val(val)
        else:
            return f"\x1b[2m{prefix}\x1b[0m\x1b[1;31m{key}\x1b[0m\x1b[2m{suffix}\x1b[0m"

    return re.sub(pattern, repl, msg)

# --- Object Flattening ---
def flatten_obj(val, prefix=""):
    res = []
    if isinstance(val, dict):
        for k in sorted(val.keys()):
            p = f"{prefix} > {k}" if prefix else str(k)
            res.extend(flatten_obj(val[k], p))
    elif isinstance(val, list):
        for i, elem in enumerate(val):
            p = f"{prefix}[{i}]" if prefix else f"[{i}]"
            res.extend(flatten_obj(elem, p))
    else:
        if val is not None:
            res.append((prefix, val))
    return res

def lookup_nested(obj, key_expr):
    parts = [p.strip() for p in key_expr.split(">")]
    curr = obj
    for p in parts:
        if isinstance(curr, dict) and p in curr:
            curr = curr[p]
        else:
            return None
    return curr

# --- Timestamp Parsing ---
def parse_timestamp(val):
    if val is None:
        return ""
    if isinstance(val, (int, float)):
        num = float(val)
        if num > 100000000000: num /= 1000.0
        import datetime
        dt = datetime.datetime.fromtimestamp(num, datetime.timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%S.000Z")
    s = str(val)
    if s.isdigit():
        num = float(s)
        if num > 100000000000: num /= 1000.0
        import datetime
        dt = datetime.datetime.fromtimestamp(num, datetime.timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%S.000Z")
    return s

def main():
    parser = argparse.ArgumentParser(description="fblog - JSON log viewer", add_help=False)
    parser.add_argument("input", nargs="?", default="-")
    parser.add_argument("-a", "--additional-value", action="append", default=[])
    parser.add_argument("--config-file")
    parser.add_argument("-m", "--message-key", action="append", default=[])
    parser.add_argument("--print-lua", action="store_true")
    parser.add_argument("-t", "--time-key", action="append", default=[])
    parser.add_argument("-l", "--level-key", action="append", default=[])
    parser.add_argument("--map-level", action="append", default=[])
    parser.add_argument("-d", "--dump-all", action="store_true")
    parser.add_argument("-x", "--excluded-value", action="append", default=[])
    parser.add_argument("-p", "--with-prefix", action="store_true")
    parser.add_argument("-f", "--filter")
    parser.add_argument("--no-implicit-filter-return-statement", action="store_true")
    parser.add_argument("--main-line-format")
    parser.add_argument("--additional-value-format")
    parser.add_argument("-s", "--substitute", action="store_true")
    parser.add_argument("-c", "--context-key", default="context")
    parser.add_argument("-F", "--placeholder-format", default="{key}")
    parser.add_argument("-h", "--help", action="store_true")
    parser.add_argument("-V", "--version", action="store_true")

    args, unknown = parser.parse_known_args()

    if args.version:
        print("fblog 4.17.0")
        sys.exit(0)

    if args.help:
        print('''json log viewer

Usage: executable [OPTIONS] [INPUT]

Arguments:
  [INPUT]  Sets the input file to use, otherwise assumes stdin [default: -]

Options:
  -a, --additional-value <additional-value>
          adds additional values
      --config-file <config-file>
          configuration file to load
  -m, --message-key <message-key>
          Adds an additional key to detect the message in the log entry. The first matching key will be assigned to `fblog_message`.
      --print-lua
          Prints lua init expressions. Used for fblog debugging.
  -t, --time-key <time-key>
          Adds an additional key to detect the time in the log entry. The first matching key will be assigned to `fblog_timestamp`.
  -l, --level-key <level-key>
          Adds an additional key to detect the level in the log entry. The first matching key will be assigned to `fblog_level`.
      --map-level <from=to>
          Rewrite the log level from one value to another.
  -d, --dump-all
          dumps all values
  -x, --excluded-value <excluded-value>
          Excludes values (--dump-all is enabled implicitly)
  -p, --with-prefix
          consider all text before opening curly brace as prefix
  -f, --filter <filter>
          lua expression to filter log entries. `message ~= nil and string.find(message, "text.*") ~= nil`
      --no-implicit-filter-return-statement
          if you pass a filter expression 'return' is automatically prepended. Pass this switch to disable the implicit return.
      --main-line-format <main-line-format>
          Formats the main fblog output. All log values can be used. fblog provides sanitized variables starting with `fblog_`.
      --additional-value-format <additional-value-format>
          Formats the additional value fblog output.
  -s, --substitute
          Enable substitution of placeholders in the log messages with their corresponding values from the context.
  -c, --context-key <context-key>
          Use this key as the source of substitutions for the message. Value can either be an array ({1}) or an object ({key}).
  -F, --placeholder-format <placeholder-format>
          The format that should be used for substituting values in the message, where the key is the literal word `key`. Example: [[key]] or ${key}.
  -h, --help
          Print help
  -V, --version
          Print version''')
        sys.exit(0)

    # Config loading
    cfg = dict(DEFAULT_CONFIG)
    cfg_file = args.config_file
    if not cfg_file:
        xdg_cfg = os.path.expanduser("~/.config/fblog.toml")
        if os.path.exists(xdg_cfg):
            cfg_file = xdg_cfg

    if cfg_file and os.path.exists(cfg_file):
        try:
            with open(cfg_file, "rb") as f:
                loaded = toml.load(f)
                for k, v in loaded.items():
                    if k in cfg:
                        cfg[k] = v
        except Exception:
            pass

    # Merge CLI options
    message_keys = list(args.message_key) + cfg["message_keys"]
    time_keys = list(args.time_key) + cfg["time_keys"]
    level_keys = list(args.level_key) + cfg["level_keys"]
    level_map = dict(cfg["level_map"])
    for m in args.map_level:
        if "=" in m:
            k, v = m.split("=", 1)
            level_map[k] = v

    main_line_format = args.main_line_format if args.main_line_format else cfg["main_line_format"]
    additional_value_format = args.additional_value_format if args.additional_value_format else cfg["additional_value_format"]

    dump_all = args.dump_all or bool(args.excluded-value)
    dump_all_exclude = set(cfg["dump_all_exclude"]).union(set(args.excluded_value))
    additional_value_keys = cfg["always_print_fields"] + args.additional_value

    # Input stream
    if args.input == "-":
        stream = sys.stdin
    else:
        try:
            stream = open(args.input, "r", encoding="utf-8", errors="replace")
        except Exception:
            print(f"\nthread 'main' (1010) panicked at src/main.rs:105:68:\nCan't open file: {args.input}", file=sys.stderr)
            sys.exit(101)

    for line in stream:
        raw_line = line.rstrip("\r\n")

        prefix = None
        json_str = raw_line
        if args.with_prefix:
            idx = raw_line.find("{")
            if idx != -1:
                prefix = raw_line[:idx]
                json_str = raw_line[idx:]
            else:
                print(f"\x1b[1;38;2;255;135;22m??? >\x1b[0m {raw_line}")
                continue

        try:
            obj = json.loads(json_str)
            if not isinstance(obj, dict):
                raise ValueError("Not a dict")
        except Exception:
            print(f"\x1b[1;38;2;255;135;22m??? >\x1b[0m {raw_line}")
            continue

        # Lua Filter
        if args.filter:
            lua_init = generate_lua_init(obj)
            if args.print_lua:
                print(lua_init)

            # Setup env
            env = LuaEnv()
            for k, v in obj.items():
                env[sanitize_key(k)] = v

            try:
                keep = eval_lua_filter(args.filter, env, args.no_implicit_filter_return_statement)
                if not keep:
                    continue
            except Exception as e:
                print(f"\x1b[31mFailed to apply filter expression\x1b[0m: '{e}'")
                continue

        # Extract fblog_ variables
        fblog_timestamp = ""
        for tk in time_keys:
            if tk in obj:
                fblog_timestamp = parse_timestamp(obj[tk])
                break

        fblog_level = "unknown"
        for lk in level_keys:
            if lk in obj:
                v_str = str(obj[lk])
                fblog_level = level_map.get(v_str, v_str)
                break

        fblog_message = ""
        for mk in message_keys:
            if mk in obj:
                fblog_message = str(obj[mk])
                if args.substitute:
                    ctx_data = obj.get(args.context_key)
                    fblog_message = substitute_placeholders(fblog_message, ctx_data, args.placeholder_format)
                break

        fblog_prefix = prefix if prefix is not None else ""

        # Prepare Handlebars context
        hbs_ctx = dict(obj)
        hbs_ctx["fblog_timestamp"] = fblog_timestamp
        hbs_ctx["fblog_level"] = fblog_level
        hbs_ctx["fblog_message"] = fblog_message
        hbs_ctx["fblog_prefix"] = fblog_prefix

        # Render Main Line
        try:
            main_line = render_hbs(main_line_format, hbs_ctx)
            print(main_line)
        except Exception as e:
            print(f"\x1b[1;31m??? >\x1b[0m Failed to process line: {e}")
            continue

        # Render Additional Values
        if dump_all:
            keys_to_dump = [k for k in sorted(obj.keys()) if k not in dump_all_exclude]
            for k in keys_to_dump:
                for flat_k, leaf_v in flatten_obj(obj[k], k):
                    if leaf_v is not None:
                        add_ctx = {"key": flat_k, "value": leaf_v}
                        print(render_hbs(additional_value_format, add_ctx))
        else:
            for ak in additional_value_keys:
                val = lookup_nested(obj, ak)
                if val is not None:
                    for flat_k, leaf_v in flatten_obj(val, ak):
                        if leaf_v is not None:
                            add_ctx = {"key": flat_k, "value": leaf_v}
                            print(render_hbs(additional_value_format, add_ctx))

if __name__ == "__main__":
    main()
