#!/usr/bin/env python3
import sys, os, json, re, argparse

# Try loading toml parser
try:
    import tomllib as toml
except ImportError:
    import tomli as toml

DEFAULT_CONFIG = {
    "message_keys": ["short_message", "msg", "message"],
    "time_keys": ["timestamp", "time", "@timestamp"],
    "level_keys": ["level", "severity", "log.level", "loglevel"],
    "always_print_fields": [],
    "dump_all_exclude": [],
    "main_line_format": "{{bold(fixed_size 19 fblog_timestamp)}} {{level_style (uppercase (fixed_size 5 fblog_level))}}:{{#if fblog_prefix}} {{bold(cyan fblog_prefix)}}{{/if}} {{fblog_message}}",
    "additional_value_format": "{{bold (color_rgb 150 150 150 (min_size 25 key))}}: {{value}}",
    "level_map": {}
}

# --- Handlebars Helper Engine ---
def helper_bold(v): return f"\x1b[1m{v}\x1b[0m"
def helper_red(v): return f"\x1b[31m{v}\x1b[0m"
def helper_green(v): return f"\x1b[32m{v}\x1b[0m"
def helper_yellow(v): return f"\x1b[33m{v}\x1b[0m"
def helper_blue(v): return f"\x1b[34m{v}\x1b[0m"
def helper_purple(v): return f"\x1b[35m{v}\x1b[0m"
def helper_cyan(v): return f"\x1b[36m{v}\x1b[0m"
def helper_color_rgb(r, g, b, v): return f"\x1b[38;2;{r};{g};{b}m{v}\x1b[0m"
def helper_uppercase(v): return str(v).upper()
def helper_fixed_size(sz, v):
    s = str(v)
    sz = int(sz)
    if len(s) < sz:
        return s.rjust(sz)
    return s[:sz]
def helper_min_size(sz, v):
    s = str(v)
    sz = int(sz)
    if len(s) < sz:
        return s.rjust(sz)
    return s
def helper_level_style(v):
    lvl = str(v).lower()
    if lvl == "trace": return f"\x1b[1;36m{v}\x1b[0m"
    if lvl == "debug": return f"\x1b[1;34m{v}\x1b[0m"
    if lvl == "info": return f"\x1b[1;32m{v}\x1b[0m"
    if lvl in ("warn", "warning"): return f"\x1b[1;33m{v}\x1b[0m"
    if lvl in ("error", "err"): return f"\x1b[1;31m{v}\x1b[0m"
    return f"\x1b[1;35m{v}\x1b[0m"
def helper_lookup(obj, key):
    if isinstance(obj, dict):
        return obj.get(key, "")
    return ""
def helper_eq(a, b): return a == b
def helper_ne(a, b): return a != b
def helper_gt(a, b): return a > b
def helper_lt(a, b): return a < b

HELPERS = {
    "bold": helper_bold, "red": helper_red, "green": helper_green,
    "yellow": helper_yellow, "blue": helper_blue, "purple": helper_purple,
    "cyan": helper_cyan, "color_rgb": helper_color_rgb, "uppercase": helper_uppercase,
    "fixed_size": helper_fixed_size, "min_size": helper_min_size,
    "level_style": helper_level_style, "lookup": helper_lookup,
    "eq": helper_eq, "ne": helper_ne, "gt": helper_gt, "lt": helper_lt
}

def tokenize_hbs(s):
    tokens = []
    i = 0
    while i < len(s):
        if s[i].isspace():
            i += 1
            continue
        if s[i] in "()":
            tokens.append(s[i])
            i += 1
            continue
        if s[i] in "\"'":
            quote = s[i]
            i += 1
            start = i
            while i < len(s) and s[i] != quote:
                if s[i] == "\\" and i + 1 < len(s):
                    i += 2
                else:
                    i += 1
            tokens.append(("STRING", s[start:i]))
            if i < len(s): i += 1
            continue
        if s[i] == "[":
            start = i + 1
            while i < len(s) and s[i] != "]":
                i += 1
            tokens.append(("ID", s[start:i]))
            if i < len(s): i += 1
            continue
        start = i
        while i < len(s) and not s[i].isspace() and s[i] not in "()\"'[]":
            i += 1
        tok = s[start:i]
        if tok.isdigit() or (tok.startswith("-") and tok[1:].isdigit()):
            tokens.append(("INT", int(tok)))
        elif tok == "true":
            tokens.append(("BOOL", True))
        elif tok == "false":
            tokens.append(("BOOL", False))
        else:
            tokens.append(("ID", tok))
    return tokens

def parse_expr_tokens(tokens, ctx):
    idx = 0
    def eval_next():
        nonlocal idx
        if idx >= len(tokens):
            return ""
        tok = tokens[idx]
        if tok == "(":
            idx += 1
            res = eval_next()
            if idx < len(tokens) and tokens[idx] == ")":
                idx += 1
            return res
        idx += 1
        if isinstance(tok, tuple):
            ttype, val = tok
            if ttype == "STRING":
                return val
            elif ttype in ("INT", "BOOL"):
                return val
            elif ttype == "ID":
                if val in HELPERS:
                    func = HELPERS[val]
                    args = []
                    while idx < len(tokens) and tokens[idx] != ")":
                        args.append(eval_next())
                    return func(*args)
                else:
                    return ctx.get(val, "")
        return ""

    return eval_next()

def render_hbs(tmpl, ctx):
    # Process {{#if cond}} ... {{else}} ... {{/if}}
    def render_block(m):
        cond_str = m.group(1).strip()
        body = m.group(2)
        true_body = body
        false_body = ""
        if "{{else}}" in body:
            parts = body.split("{{else}}", 1)
            true_body, false_body = parts[0], parts[1]

        cond_val = parse_expr_tokens(tokenize_hbs(cond_str), ctx)
        if cond_val and cond_val != "0" and cond_val != "false":
            return render_hbs(true_body, ctx)
        else:
            return render_hbs(false_body, ctx)

    s = re.sub(r'\{\{#if\s+(.*?)\}\}(.*?)\{\{/if\}\}', render_block, tmpl, flags=re.DOTALL)

    # Process {{ expr }}
    def render_tag(m):
        expr_str = m.group(1).strip()
        val = parse_expr_tokens(tokenize_hbs(expr_str), ctx)
        return str(val)

    s = re.sub(r'\{\{(.*?)\}\}', render_tag, s)
    return s

# --- Lua Initialization & Filter ---
def sanitize_key(k):
    return re.sub(r'[^a-zA-Z]', '_', str(k))

def to_lua_val(v, inside_array=False):
    if inside_array and isinstance(v, (list, dict)):
        return '"unsupported"'
    if v is None:
        return "nil"
    elif isinstance(v, bool):
        return "true" if v else "false"
    elif isinstance(v, (int, float)):
        return str(v)
    elif isinstance(v, str):
        escaped = v.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t")
        return f'"{escaped}"'
    elif isinstance(v, list):
        elems = [to_lua_val(x, inside_array=True) for x in v]
        return "{" + ",".join(elems) + "}"
    elif isinstance(v, dict):
        items = []
        for k, sub_v in sorted(v.items(), key=lambda x: str(x[0])):
            items.append(f"{sanitize_key(k)} = {to_lua_val(sub_v, inside_array=False)}")
        return "{" + ",".join(items) + "}"
    return "nil"

def generate_lua_init(json_obj):
    lines = []
    for k, v in sorted(json_obj.items(), key=lambda x: sanitize_key(x[0])):
        san_k = sanitize_key(k)
        lines.append(f"{san_k} = {to_lua_val(v)}")
    return "\n".join(lines)

class LuaEnv(dict):
    def __getitem__(self, item):
        return self.get(item, None)

def lua_to_python_expr(expr):
    strings = []
    def save_str(m):
        strings.append(m.group(0))
        return f"__STR_{len(strings)-1}__"

    s = re.sub(r'"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'', save_str, expr)
    s = re.sub(r'\b~=\b|~=', '!=', s)
    s = re.sub(r'\band\b', ' and ', s)
    s = re.sub(r'\bor\b', ' or ', s)
    s = re.sub(r'\bnot\b', ' not ', s)
    s = re.sub(r'\bnil\b', ' None ', s)
    s = re.sub(r'\btrue\b', ' True ', s)
    s = re.sub(r'\bfalse\b', ' False ', s)
    s = re.sub(r'\.\.', '+', s)

    s = re.sub(r'\bstring\.find\b', 'lua_string_find', s)
    s = re.sub(r'\bstring\.match\b', 'lua_string_match', s)
    s = re.sub(r'\bstring\.lower\b', 'lua_string_lower', s)
    s = re.sub(r'\bstring\.upper\b', 'lua_string_upper', s)

    for i, st in enumerate(strings):
        s = s.replace(f"__STR_{i}__", st)
    return s

def lua_string_find(s, pattern):
    if s is None or pattern is None:
        return None
    py_pat = pattern.replace('%d', r'\d').replace('%a', r'[a-zA-Z]').replace('%w', r'\w').replace('%s', r'\s')
    m = re.search(py_pat, str(s))
    if m:
        return (m.start() + 1, m.end())
    return None

def lua_string_match(s, pattern):
    if s is None or pattern is None:
        return None
    py_pat = pattern.replace('%d', r'\d').replace('%a', r'[a-zA-Z]').replace('%w', r'\w').replace('%s', r'\s')
    m = re.search(py_pat, str(s))
    if m:
        return m.group(1) if m.groups() else m.group(0)
    return None

def eval_lua_filter(expr, env, no_implicit_return=False):
    py_expr = lua_to_python_expr(expr)
    if "return " in py_expr:
        py_expr = py_expr.split("return ", 1)[1]
    try:
        res = eval(py_expr, {"__builtins__": None, "lua_string_find": lua_string_find, "lua_string_match": lua_string_match, "True": True, "False": False, "None": None}, env)
        return bool(res)
    except Exception as e:
        raise RuntimeError(str(e))

# --- Context Value Substitution (-s) ---
def format_ctx_val(v):
    if v is None:
        return "\x1b[1mnull\x1b[0m"
    elif isinstance(v, bool):
        return "\x1b[1;32mtrue\x1b[0m" if v else "\x1b[1;31mfalse\x1b[0m"
    elif isinstance(v, (int, float)):
        return f"\x1b[1;36m{v}\x1b[0m"
    elif isinstance(v, str):
        return f"\x1b[1;33m{v}\x1b[0m"
    elif isinstance(v, list):
        elems = "\x1b[2m, \x1b[0m".join(format_ctx_val(x) for x in v)
        return f"\x1b[2m[\x1b[0m{elems}\x1b[2m]\x1b[0m"
    elif isinstance(v, dict):
        items = []
        for k in sorted(v.keys()):
            val_str = format_ctx_val(v[k])
            items.append(f"\x1b[35m{k}\x1b[0m\x1b[2m: \x1b[0m{val_str}")
        kv_pairs = "\x1b[2m, \x1b[0m".join(items)
        return f"\x1b[2m{{\x1b[0m{kv_pairs}\x1b[2m}}\x1b[0m"
    return str(v)

def substitute_placeholders(msg, ctx_data, pf="{key}"):
    prefix = pf.split("key")[0]
    suffix = pf.split("key")[1]
    pattern = re.escape(prefix) + r'([a-zA-Z0-9_-]+)' + re.escape(suffix)

    def repl(m):
        key = m.group(1)
        val = None
        found = False
        if isinstance(ctx_data, dict):
            if key in ctx_data:
                val = ctx_data[key]
                found = True
        elif isinstance(ctx_data, list):
            if key.isdigit():
                idx = int(key)
                if 0 <= idx < len(ctx_data):
                    val = ctx_data[idx]
                    found = True
        if found:
            return format_ctx_val(val)
        else:
            return f"\x1b[2m{prefix}\x1b[0m\x1b[1;31m{key}\x1b[0m\x1b[2m{suffix}\x1b[0m"

    return re.sub(pattern, repl, msg)

# --- Object Flattening ---
def flatten_obj(val, prefix=""):
    res = []
    if isinstance(val, dict):
        for k in sorted(val.keys()):
            p = f"{prefix} > {k}" if prefix else str(k)
            res.extend(flatten_obj(val[k], p))
    elif isinstance(val, list):
        for i, elem in enumerate(val):
            p = f"{prefix}[{i}]" if prefix else f"[{i}]"
            res.extend(flatten_obj(elem, p))
    else:
        if val is not None:
            res.append((prefix, val))
    return res

def lookup_nested(obj, key_expr):
    parts = [p.strip() for p in key_expr.split(">")]
    curr = obj
    for p in parts:
        if isinstance(curr, dict) and p in curr:
            curr = curr[p]
        else:
            return None
    return curr

# --- Timestamp Parsing ---
def parse_timestamp(val):
    if val is None:
        return ""
    if isinstance(val, (int, float)):
        num = float(val)
        if num > 100000000000: num /= 1000.0
        import datetime
        dt = datetime.datetime.fromtimestamp(num, datetime.timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%S.000Z")
    s = str(val)
    if s.isdigit():
        num = float(s)
        if num > 100000000000: num /= 1000.0
        import datetime
        dt = datetime.datetime.fromtimestamp(num, datetime.timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%S.000Z")
    return s

def main():
    parser = argparse.ArgumentParser(description="fblog - JSON log viewer", add_help=False)
    parser.add_argument("input", nargs="?", default="-")
    parser.add_argument("-a", "--additional-value", action="append", default=[])
    parser.add_argument("--config-file")
    parser.add_argument("-m", "--message-key", action="append", default=[])
    parser.add_argument("--print-lua", action="store_true")
    parser.add_argument("-t", "--time-key", action="append", default=[])
    parser.add_argument("-l", "--level-key", action="append", default=[])
    parser.add_argument("--map-level", action="append", default=[])
    parser.add_argument("-d", "--dump-all", action="store_true")
    parser.add_argument("-x", "--excluded-value", action="append", default=[])
    parser.add_argument("-p", "--with-prefix", action="store_true")
    parser.add_argument("-f", "--filter")
    parser.add_argument("--no-implicit-filter-return-statement", action="store_true")
    parser.add_argument("--main-line-format")
    parser.add_argument("--additional-value-format")
    parser.add_argument("-s", "--substitute", action="store_true")
    parser.add_argument("-c", "--context-key", default="context")
    parser.add_argument("-F", "--placeholder-format", default="{key}")
    parser.add_argument("-h", "--help", action="store_true")
    parser.add_argument("-V", "--version", action="store_true")

    args, unknown = parser.parse_known_args()

    if args.version:
        print("fblog 4.17.0")
