    for line in stream:
        raw_line = line.rstrip("\r\n")

        prefix = None
        json_str = raw_line
        if args.with_prefix:
            idx = raw_line.find("{")
            if idx != -1:
                prefix = raw_line[:idx]
                json_str = raw_line[idx:]
            else:
                print(f"\x1b[1;38;2;255;135;22m??? >\x1b[0m {raw_line}")
